package com.mdt.offlinemusic;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.database.Cursor;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.io.*;
import java.security.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import org.json.*;

/** Separate local encrypted photo/video vault. Never adds media to MediaStore. */
public class VaultActivity extends Activity {
 private static final int PICK=741; private static final String KEY_ALIAS="MDT_VAULT_AES_V1";
 private final Handler ui=new Handler(Looper.getMainLooper());
 private LinearLayout content; private SharedPreferences prefs; private boolean unlocked=false,busy=false,selecting=false;
 private final ArrayList<File> tempFiles=new ArrayList<>();
 private final ArrayList<JSONObject> entries=new ArrayList<>();
 private File vaultDir(){File d=new File(getFilesDir(),"vault");if(!d.exists())d.mkdirs();return d;}
 private File indexFile(){return new File(vaultDir(),"index.enc");}
 private SecretKey secret() throws Exception {java.security.KeyStore store=java.security.KeyStore.getInstance("AndroidKeyStore");store.load(null);
  if(!store.containsAlias(KEY_ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(KEY_ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());g.generateKey();}
  return ((java.security.KeyStore.SecretKeyEntry)store.getEntry(KEY_ALIAS,null)).getSecretKey();}
 private void encrypt(InputStream plain,OutputStream encrypted) throws Exception {Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,secret());byte[] iv=cipher.getIV();encrypted.write(iv.length);encrypted.write(iv);try(CipherOutputStream c=new CipherOutputStream(encrypted,cipher)){byte[] b=new byte[65536];int n;while((n=plain.read(b))!=-1)c.write(b,0,n);}}
 private void decrypt(InputStream encrypted,OutputStream plain) throws Exception {int n=encrypted.read();if(n!=12)throw new IOException("IV không hợp lệ");byte[] iv=new byte[n];new DataInputStream(encrypted).readFully(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,secret(),new GCMParameterSpec(128,iv));try(CipherInputStream in=new CipherInputStream(encrypted,c)){byte[] b=new byte[65536];int size;while((size=in.read(b))!=-1)plain.write(b,0,size);}}
 private void load() throws Exception {entries.clear();if(!indexFile().exists())return;ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(indexFile())){decrypt(in,out);}JSONArray json=new JSONArray(out.toString("UTF-8"));for(int i=0;i<json.length();i++)entries.add(json.getJSONObject(i));}
 private void save() throws Exception {JSONArray data=new JSONArray();for(JSONObject e:entries)data.put(e);File temp=new File(vaultDir(),"index.tmp");try(InputStream in=new ByteArrayInputStream(data.toString().getBytes("UTF-8"));OutputStream out=new FileOutputStream(temp)){encrypt(in,out);}if(indexFile().exists()&&!indexFile().delete())throw new IOException("Không ghi được mục lục");if(!temp.renameTo(indexFile()))throw new IOException("Không lưu được mục lục");}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("vault_security",MODE_PRIVATE);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);showGate();}
 private String digest(String text){try{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] bytes=md.digest(text.getBytes("UTF-8"));StringBuilder sb=new StringBuilder();for(byte x:bytes)sb.append(String.format(Locale.US,"%02x",x&255));return sb.toString();}catch(Exception e){return "";}}
 private TextView button(String name,Runnable task){TextView b=new TextView(this);b.setText(name);b.setTextColor(-1);b.setTextSize(16);b.setGravity(Gravity.CENTER);b.setPadding(15,16,15,16);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xFFAB79EF);bg.setCornerRadius(22);b.setBackground(bg);b.setOnClickListener(v->task.run());return b;}
 private void add(String s, int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xFF202336);t.setTextSize(size);t.setPadding(8,14,8,14);content.addView(t);}
 private void page(String heading){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(22,32,22,35);content.setBackgroundColor(0xFFF4F2FA);scroll.addView(content);setContentView(scroll);add(heading,25);}
 private void showGate(){unlocked=false;page("Khu vực riêng tư");add("Nhập mật khẩu lớp thứ hai để mở Album ẩn",14);String expected=prefs.getString("pin_hash","");if(expected.isEmpty()){openVault();return;}if(prefs.getBoolean("biometric",false)&&Build.VERSION.SDK_INT>=28){new AlertDialog.Builder(this).setTitle("Mở khóa Album ẩn").setItems(new String[]{"Nhập PIN","Dùng vân tay / sinh trắc học"},(d,w)->{if(w==1)biometricUnlock();else verifyPin(expected);}).setCancelable(false).show();}else verifyPin(expected);}
 interface PinAction{void done(String pin);}
 private void pinPrompt(String title,PinAction action){EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8)});input.setHint("Mã PIN 4–8 số");new AlertDialog.Builder(this).setTitle(title).setView(input).setCancelable(false).setNegativeButton("Hủy",(d,w)->{if(!unlocked)finish();}).setPositiveButton("Tiếp tục",(d,w)->{String pin=input.getText().toString();if(!pin.matches("[0-9]{4,8}")){Toast.makeText(this,"PIN cần 4–8 chữ số",Toast.LENGTH_LONG).show();if(!unlocked)finish();return;}action.done(pin);}).show();}
 private void verifyPin(String expected){pinPrompt("Mở khóa Album ẩn",value->{if(expected.equals(digest(value)))openVault();else{Toast.makeText(this,"Mã PIN không đúng",Toast.LENGTH_SHORT).show();finish();}});}
 private void biometricUnlock(){if(Build.VERSION.SDK_INT<28){showGate();return;}try{android.hardware.biometrics.BiometricPrompt prompt=new android.hardware.biometrics.BiometricPrompt.Builder(this).setTitle("MDT Music — Album ẩn").setSubtitle("Xác thực để mở kho mã hóa").setNegativeButton("Nhập PIN",getMainExecutor(),(dialog,which)->verifyPin(prefs.getString("pin_hash",""))).build();prompt.authenticate(new android.os.CancellationSignal(),getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult result){openVault();}@Override public void onAuthenticationError(int code,CharSequence message){if(!isFinishing())verifyPin(prefs.getString("pin_hash",""));}});}catch(Exception e){verifyPin(prefs.getString("pin_hash",""));}}
 private void openVault(){try{load();unlocked=true;showHome();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Không thể mở kho mã hóa").setMessage("Không đọc được dữ liệu hoặc khóa thiết bị đã thay đổi. Không xóa hay gỡ ứng dụng để tránh mất dữ liệu.\n"+e.getMessage()).setPositiveButton("Đóng",(d,w)->finish()).show();}}
 private void showHome(){if(!unlocked)return;page("Album ẩn");add(entries.size()+" ảnh/video được mã hóa trong bộ nhớ riêng",14);content.addView(button("+ Thêm ảnh/video",()->{if(busy)return;selecting=true;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","video/*"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);}));
 content.addView(button("Cài đặt Album ẩn",this::settings));content.addView(button("Ứng dụng ẩn trên Xiaomi",this::appHelp));
 for(JSONObject j:new ArrayList<>(entries)){String id=j.optString("id");String label=j.optString("name","Tệp")+"  ·  "+(j.optString("mime").startsWith("video/")?"Video":"Ảnh");LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);TextView name=new TextView(this);name.setText(label);name.setTextColor(0xFF202336);name.setTextSize(14);name.setPadding(4,20,4,20);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));name.setOnClickListener(v->view(j));TextView remove=button("Xóa",()->new AlertDialog.Builder(this).setTitle("Xóa khỏi Album ẩn?").setMessage("Tệp đã xóa sẽ không thể khôi phục nếu chưa sao lưu.").setNegativeButton("Hủy",null).setPositiveButton("Xóa",(d,w)->{new File(vaultDir(),id+".vault").delete();entries.remove(j);try{save();}catch(Exception ex){error(ex);}showHome();}).show());row.addView(remove);content.addView(row);}
 }
 private void settings(){page("Bảo mật Album ẩn");content.addView(button("Đặt / đổi mật khẩu lớp thứ hai",()->pinPrompt("Tạo mã PIN mới",first->pinPrompt("Nhập lại PIN",second->{if(!first.equals(second)){Toast.makeText(this,"PIN không khớp",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("pin_hash",digest(first)).apply();Toast.makeText(this,"Đã đặt PIN",Toast.LENGTH_SHORT).show();}))));
 content.addView(button("Tắt mật khẩu lớp thứ hai",()->{if(!prefs.contains("pin_hash"))return;pinPrompt("Nhập PIN hiện tại",pin->{if(digest(pin).equals(prefs.getString("pin_hash",""))){prefs.edit().remove("pin_hash").apply();Toast.makeText(this,"Đã tắt PIN",Toast.LENGTH_SHORT).show();}else Toast.makeText(this,"PIN sai",Toast.LENGTH_SHORT).show();});}));
 content.addView(button("Bật / tắt mở khóa sinh trắc học",()->{if(Build.VERSION.SDK_INT<28||!prefs.contains("pin_hash")){Toast.makeText(this,"Cần Android 9+ và PIN lớp hai",Toast.LENGTH_LONG).show();return;}boolean enabled=!prefs.getBoolean("biometric",false);prefs.edit().putBoolean("biometric",enabled).apply();Toast.makeText(this,enabled?"Đã bật sinh trắc học":"Đã tắt sinh trắc học",Toast.LENGTH_SHORT).show();}));add("• Tự khóa khi rời Album ẩn\n• Chặn ảnh chụp màn hình và hình xem trước đa nhiệm\n• Ảnh/video mã hóa AES-256-GCM bằng Android Keystore\n• Không tự xóa tệp gốc",14);
 content.addView(button("Quay lại Album ẩn",this::showHome));}
 private void appHelp(){page("Ẩn ứng dụng trên Xiaomi");add("MDT Music không thể tự gỡ icon của ứng dụng khác khỏi Xiaomi Launcher. Hãy dùng Bảo mật → Ẩn ứng dụng trên Xiaomi. Không chọn Gỡ cài đặt vì sẽ xóa ứng dụng.",16);content.addView(button("Mở cài đặt Android",()->{try{startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}catch(Exception e){error(e);}}));content.addView(button("Quay lại",this::showHome));}
 private void error(Exception e){new AlertDialog.Builder(this).setTitle("Lỗi").setMessage(e.getMessage()).setPositiveButton("Đóng",null).show();}
 private String display(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception e){}return "Tệp riêng tư";}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK)selecting=false;if(request!=PICK||result!=RESULT_OK||data==null||busy)return;ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());if(uris.isEmpty())return;busy=true;ProgressDialog progress=new ProgressDialog(this);progress.setMessage("Đang mã hóa và lưu... Không đóng ứng dụng");progress.setCancelable(false);progress.show();new Thread(()->{int ok=0;String fail="";for(Uri uri:uris){String id=UUID.randomUUID().toString();File temp=new File(vaultDir(),id+".partial");try{String mime=getContentResolver().getType(uri);if(mime==null||!(mime.startsWith("image/")||mime.startsWith("video/")))throw new IOException("Không hỗ trợ định dạng này");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("Không đọc được tệp");encrypt(in,out);}File target=new File(vaultDir(),id+".vault");if(!temp.renameTo(target))throw new IOException("Không lưu được tệp");JSONObject row=new JSONObject();row.put("id",id);row.put("name",display(uri));row.put("mime",mime);entries.add(row);save();ok++;}catch(Exception ex){temp.delete();fail=ex.getMessage();}}int success=ok;String details=fail;ui.post(()->{busy=false;progress.dismiss();showHome();new AlertDialog.Builder(this).setTitle("Đã nhập "+success+"/"+uris.size()+" tệp").setMessage("Bản gốc trên điện thoại chưa bị xóa. Chỉ xóa bản gốc sau khi kiểm tra được tệp trong Album ẩn."+(details.isEmpty()?"":"\nLỗi: "+details)).setPositiveButton("OK",null).show();});}).start();}
 private void view(JSONObject row){String id=row.optString("id");File encrypted=new File(vaultDir(),id+".vault");if(!encrypted.isFile()){Toast.makeText(this,"Không tìm thấy file mã hóa",Toast.LENGTH_SHORT).show();return;}
 if(row.optString("mime").startsWith("image/")){try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(encrypted)){decrypt(in,out);}byte[] bytes=out.toByteArray();Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);Arrays.fill(bytes,(byte)0);if(bitmap==null)throw new IOException("Ảnh không hợp lệ");ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);new AlertDialog.Builder(this).setView(image).setPositiveButton("Đóng",null).show();}catch(Exception e){error(e);}return;}
 busy=true;ProgressDialog wait=new ProgressDialog(this);wait.setMessage("Đang giải mã video...");wait.setCancelable(false);wait.show();new Thread(()->{File tmp=null;try{tmp=File.createTempFile("mdt_preview_",".mp4",getCacheDir());try(InputStream in=new FileInputStream(encrypted);OutputStream out=new FileOutputStream(tmp)){decrypt(in,out);}File ready=tmp;ui.post(()->{busy=false;wait.dismiss();tempFiles.add(ready);VideoView player=new VideoView(this);player.setVideoPath(ready.getAbsolutePath());MediaController controls=new MediaController(this);player.setMediaController(controls);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(row.optString("name")).setView(player).setPositiveButton("Đóng",null).create();dialog.setOnDismissListener(d->{player.stopPlayback();ready.delete();tempFiles.remove(ready);});dialog.show();player.start();});}catch(Exception ex){if(tmp!=null)tmp.delete();Exception reason=ex;ui.post(()->{busy=false;wait.dismiss();error(reason);});}}).start();}
 @Override protected void onStop(){super.onStop();if(unlocked&&!busy&&!selecting){unlocked=false;for(File f:tempFiles)f.delete();tempFiles.clear();finish();}}
}
